changeSet.sql:
CREATE TABLE audit_log_entries (
    id              uuid NOT NULL,
    created_at      timestamp(6) with time zone NOT NULL,
    created_by      varchar(255),

    actor_user_id   uuid NOT NULL,
    action          varchar(100) NOT NULL,
    target_type     varchar(100) NOT NULL,
    target_id       uuid NOT NULL,
    tenant_id       uuid,
    detail          text,
    privileged      boolean NOT NULL DEFAULT false,
    occurred_at     timestamp(6) with time zone NOT NULL,

    PRIMARY KEY (id)
);

CREATE INDEX idx_audit_log_entries_tenant_id ON audit_log_entries (tenant_id);
CREATE INDEX idx_audit_log_entries_actor_user_id ON audit_log_entries (actor_user_id);
CREATE INDEX idx_audit_log_entries_target ON audit_log_entries (target_type, target_id);
CREATE INDEX idx_audit_log_entries_occurred_at ON audit_log_entries (occurred_at);

COMMENT ON TABLE audit_log_entries IS
    'Append-only platform-wide audit trail — never updated or deleted. Written only through audit.AuditApi.record(...), never directly, so every module logs through one interface instead of writing to this table by hand.';
